CREATE DATABASE IF NOT EXISTS calatayud_gastronomico CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE calatayud_gastronomico;
CREATE TABLE campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,campaign_type VARCHAR(50) NOT NULL,edition_number INT UNSIGNED NULL,description TEXT NULL,start_date DATE NULL,end_date DATE NULL,active BOOLEAN NOT NULL DEFAULT TRUE,first_visit_points INT UNSIGNED NOT NULL DEFAULT 2,repeat_visit_points INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(25) NOT NULL,phone_normalized VARCHAR(25) NOT NULL,phone_verified BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_phone(phone_normalized));
CREATE TABLE establishments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,address VARCHAR(255) NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE campaign_establishments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,establishment_id BIGINT UNSIGNED NOT NULL,display_order INT UNSIGNED NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,FOREIGN KEY(establishment_id) REFERENCES establishments(id) ON DELETE CASCADE,UNIQUE KEY uk_ce(campaign_id,establishment_id));
CREATE TABLE staff_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,password_hash VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(establishment_id) REFERENCES establishments(id) ON DELETE CASCADE);
CREATE TABLE participant_qrs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,campaign_id BIGINT UNSIGNED NOT NULL,qr_token CHAR(64) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,UNIQUE KEY uk_qr_token(qr_token),UNIQUE KEY uk_qr_user_campaign(user_id,campaign_id));
CREATE TABLE visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,establishment_id BIGINT UNSIGNED NOT NULL,staff_user_id BIGINT UNSIGNED NULL,visit_number_at_establishment INT UNSIGNED NOT NULL,participation_points INT UNSIGNED NOT NULL,validated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(establishment_id) REFERENCES establishments(id) ON DELETE CASCADE,FOREIGN KEY(staff_user_id) REFERENCES staff_users(id) ON DELETE SET NULL,INDEX idx_visit(user_id,campaign_id,establishment_id));
CREATE TABLE participations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,visit_id BIGINT UNSIGNED NOT NULL,points INT UNSIGNED NOT NULL,reason ENUM('FIRST_VISIT','REPEAT_VISIT') NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE,UNIQUE KEY uk_part_visit(visit_id));
CREATE TABLE prizes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description TEXT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE);
CREATE TABLE draws (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,draw_date DATETIME NULL,status ENUM('PENDIENTE','REALIZADO','CANCELADO') NOT NULL DEFAULT 'PENDIENTE',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE);
CREATE TABLE draw_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draw_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,participation_id BIGINT UNSIGNED NOT NULL,entry_number BIGINT UNSIGNED NOT NULL,FOREIGN KEY(draw_id) REFERENCES draws(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(participation_id) REFERENCES participations(id) ON DELETE CASCADE,UNIQUE KEY uk_entry(draw_id,participation_id),UNIQUE KEY uk_number(draw_id,entry_number));
CREATE TABLE winners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draw_id BIGINT UNSIGNED NOT NULL,prize_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,draw_entry_id BIGINT UNSIGNED NOT NULL,status ENUM('PENDIENTE','CONTACTADO','CONFIRMADO','ENTREGADO','NO_RECLAMADO') NOT NULL DEFAULT 'PENDIENTE',winner_full_name VARCHAR(200) NULL,identity_verified BOOLEAN NOT NULL DEFAULT FALSE,identity_verified_at DATETIME NULL,prize_confirmation_at DATETIME NULL,claimed_at DATETIME NULL,facebook_bonus_checked BOOLEAN NOT NULL DEFAULT FALSE,facebook_bonus_awarded BOOLEAN NOT NULL DEFAULT FALSE,notes TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(draw_id) REFERENCES draws(id) ON DELETE CASCADE,FOREIGN KEY(prize_id) REFERENCES prizes(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(draw_entry_id) REFERENCES draw_entries(id));
CREATE TABLE admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,staff_user_id BIGINT UNSIGNED NULL,admin_user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(50) NULL,entity_id BIGINT UNSIGNED NULL,metadata JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
